//! The pinned install data, embedded at build time from `pin/vibe-install.json` and
//! `pin/vibe.requirements.txt`, both generated by `tools/public/vibe-install/generate_pin.py` from the
//! official sources (Vibe's tag + `uv.lock`, `PyPI`'s JSON API, Astral's uv release with its `.sha256` files).
//!
//! [`Sources`] is what one install uses: the uv archive for this OS (URL, size, SHA-256), the requirements text
//! (its SHA-256 checked against the pin at load), the Vibe and Python versions, and the links the confirmation
//! shows. The product builds it from the embedded pin ([`Sources::pinned`]); tests build their own (a local
//! archive server, a fake uv).
//!
//! Depends on: serde, `serde_json`, sha2. Called by: [`crate::manager`], the private tests.
//! Invariant: the embedded data is parsed and checked once; a bad pin is a build defect and is reported as
//! [`PinError`], never patched up at runtime.

use std::collections::BTreeMap;

use serde::Deserialize;
use sha2::{Digest, Sha256};

const PIN_JSON: &str = include_str!("../pin/vibe-install.json");
const REQUIREMENTS: &str = include_str!("../pin/vibe.requirements.txt");

/// The embedded pin is unusable (a build defect: regenerate it with the generator).
#[derive(Debug, Clone, PartialEq, Eq, thiserror::Error)]
pub enum PinError {
    /// The JSON does not parse.
    #[error("the embedded Vibe install pin does not parse: {0}")]
    Parse(String),
    /// The requirements text is not the one the pin names.
    #[error(
        "the embedded requirements file does not match the pin (sha256 {found}, pinned {pinned})"
    )]
    Requirements {
        /// SHA-256 of the embedded text.
        found: String,
        /// SHA-256 the pin states.
        pinned: String,
    },
    /// This OS and CPU have no uv release or no Vibe wheel in the pin.
    #[error("Vibe Work cannot install Vibe on this system ({0}): no official build for it")]
    UnsupportedTarget(String),
}

#[derive(Debug, Clone, Deserialize)]
#[serde(rename_all = "camelCase")]
struct PinFile {
    vibe: VibePin,
    uv: UvPin,
}

#[derive(Debug, Clone, Deserialize)]
#[serde(rename_all = "camelCase")]
struct VibePin {
    version: String,
    python: String,
    pypi_page: String,
    docs: String,
    requirements_sha256: String,
    packages: u32,
    wheels: BTreeMap<String, Wheel>,
}

#[derive(Debug, Clone, Deserialize)]
#[serde(rename_all = "camelCase")]
struct Wheel {
    filename: String,
    bytes: u64,
    sha256: String,
}

#[derive(Debug, Clone, Deserialize)]
#[serde(rename_all = "camelCase")]
struct UvPin {
    version: String,
    release_page: String,
    assets: BTreeMap<String, UvAsset>,
}

/// One uv release archive.
#[derive(Debug, Clone, PartialEq, Eq, Deserialize)]
#[serde(rename_all = "camelCase")]
pub struct UvAsset {
    /// Download URL (Astral's GitHub release).
    pub url: String,
    /// Size in bytes.
    pub bytes: u64,
    /// Lower-case hex SHA-256 the download must have.
    pub sha256: String,
    /// `tar.gz` or `zip`.
    pub archive: String,
}

/// Everything one install uses.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Sources {
    /// `mistral-vibe` version that gets installed (the generated protocol types match it).
    pub vibe_version: String,
    /// Python version request for uv (`3.14.8`).
    pub python: String,
    /// uv version and its archive for this OS.
    pub uv_version: String,
    /// The uv archive.
    pub uv: UvAsset,
    /// uv's release page (shown in the confirmation).
    pub uv_release_page: String,
    /// `PyPI` page of the pinned `mistral-vibe` (shown in the confirmation).
    pub pypi_page: String,
    /// Vibe's official documentation (shown in the confirmation).
    pub docs: String,
    /// The hash-locked requirements file (`--require-hashes`).
    pub requirements: String,
    /// SHA-256 of `requirements`.
    pub requirements_sha256: String,
    /// Packages in the requirements file (Vibe + dependencies).
    pub packages: u32,
    /// The `mistral-vibe` wheel for this OS: file name, size and SHA-256 (shown in the confirmation).
    pub wheel: (String, u64, String),
    /// Index the packages come from (`https://pypi.org/simple`).
    pub index_url: String,
}

/// The Rust target this binary was built for, spelled like the pin's keys (`x86_64-pc-windows-msvc`,...).
#[must_use]
pub fn this_target() -> String {
    let arch = std::env::consts::ARCH;
    match std::env::consts::OS {
        "windows" => format!("{arch}-pc-windows-msvc"),
        "macos" => format!("{arch}-apple-darwin"),
        "linux" => format!("{arch}-unknown-linux-gnu"),
        other => format!("{arch}-{other}"),
    }
}

/// Lower-case hex SHA-256 of `bytes`.
#[must_use]
pub fn sha256_hex(bytes: &[u8]) -> String {
    hex(&Sha256::digest(bytes))
}

/// Lower-case hex of `bytes`.
#[must_use]
pub fn hex(bytes: &[u8]) -> String {
    use std::fmt::Write as _;
    bytes
        .iter()
        .fold(String::with_capacity(bytes.len() * 2), |mut out, b| {
            let _ = write!(out, "{b:02x}");
            out
        })
}

impl Sources {
    /// The embedded pin for `target` ([`this_target`] in the product).
    ///
    /// # Errors
    /// [`PinError`]: the pin does not parse, the requirements text differs from the pinned checksum, or
    /// `target` has no uv archive or no Vibe wheel.
    pub fn pinned(target: &str) -> Result<Self, PinError> {
        let pin: PinFile =
            serde_json::from_str(PIN_JSON).map_err(|e| PinError::Parse(e.to_string()))?;
        let found = sha256_hex(REQUIREMENTS.as_bytes());
        if found != pin.vibe.requirements_sha256 {
            return Err(PinError::Requirements {
                found,
                pinned: pin.vibe.requirements_sha256,
            });
        }
        let unsupported = || PinError::UnsupportedTarget(target.to_owned());
        let uv = pin.uv.assets.get(target).cloned().ok_or_else(unsupported)?;
        let wheel = pin
            .vibe
            .wheels
            .get(target)
            .cloned()
            .ok_or_else(unsupported)?;
        Ok(Self {
            vibe_version: pin.vibe.version,
            python: pin.vibe.python,
            uv_version: pin.uv.version,
            uv,
            uv_release_page: pin.uv.release_page,
            pypi_page: pin.vibe.pypi_page,
            docs: pin.vibe.docs,
            requirements: REQUIREMENTS.to_owned(),
            requirements_sha256: found,
            packages: pin.vibe.packages,
            wheel: (wheel.filename, wheel.bytes, wheel.sha256),
            index_url: "https://pypi.org/simple".to_owned(),
        })
    }

    /// The Vibe version the embedded pin installs (the version the generated protocol types are for).
    ///
    /// # Errors
    /// [`PinError::Parse`].
    pub fn pinned_version() -> Result<String, PinError> {
        let pin: PinFile =
            serde_json::from_str(PIN_JSON).map_err(|e| PinError::Parse(e.to_string()))?;
        Ok(pin.vibe.version)
    }
}
